import json
from collections import Counter
from pathlib import Path
p=Path('/home/debian19y/.local/state/opencode/prompt-history.jsonl')
if not p.exists():
    print('no history'); raise SystemExit
lines=p.read_text(errors='ignore').splitlines()
print('lines', len(lines))
# try parse each
texts=[]
for ln in lines:
    ln=ln.strip()
    if not ln: continue
    try:
        o=json.loads(ln)
    except Exception:
        texts.append(ln[:200]); continue
    if isinstance(o,str):
        texts.append(o)
    elif isinstance(o,dict):
        for k in ('text','prompt','content','message','input'):
            if k in o and isinstance(o[k],str):
                texts.append(o[k]); break
        else:
            texts.append(json.dumps(o,ensure_ascii=False)[:200])
    else:
        texts.append(str(o)[:200])
print('sample recent:')
for t in texts[-15:]:
    print('-', t.replace('\n',' ')[:180])
# keyword habits
kw=Counter()
for t in texts:
    tl=t.lower()
    for k in ['trellis','commit','pr','build','flash','测试','修复','继续','finish','resume','permission','allow','中文','不要','直接','实现']:
        if k in tl or k in t:
            kw[k]+=1
print('kw', dict(kw.most_common(30)))
